/* Same-origin SPA. All permissions and data boundaries are enforced by the API. */
const paths = {
  cap:'M2 9l10-5 10 5-10 5L2 9zm4 2v6c4 3 8 3 12 0v-6m4-2v7',
  dashboard:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',
  users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m14-18a4 4 0 0 1 0 8m6 10v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0z',
  book:'M4 3h12a3 3 0 0 1 3 3v15H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3m-3 15a3 3 0 0 1 3-3h13M8 7h7m-7 4h5',
  heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z',
  check:'M5 12l4 4L19 6', bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 12a2 2 0 0 0 4 0',
  settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8zm-2-6h4l1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3L1 9l2-4 3 1 3-1 1-3z',
  chart:'M4 20h17M7 16V9m5 7V4m5 12v-5', log:'M4 3h12l4 4v14H4V3zm12 0v5h4M8 12h8m-8 4h6',
  arrow:'M5 12h14m-5-5l5 5-5 5', download:'M12 3v12m-5-5l5 5 5-5M4 16v5h16v-5', upload:'M12 16V4m-5 5l5-5 5 5M4 16v5h16v-5',
  plus:'M12 5v14M5 12h14', search:'M21 21l-5-5m2-7a7 7 0 1 1-14 0 7 7 0 0 1 14 0z', clock:'M12 7v5l3 2m6-2a9 9 0 1 1-18 0 9 9 0 0 1 18 0z',
  lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v11H4V10zm8 5v2', info:'M12 11v6m0-10v1m9 4a9 9 0 1 1-18 0 9 9 0 0 1 18 0z',
  edit:'M14 4l6 6M3 21l2-7L17 2l5 5-12 12-7 2zm10 0h8', logout:'M9 3H3v18h6m-1-9h13m-5-5l5 5-5 5',
  close:'M6 6l12 12M6 18L18 6', menu:'M4 6h16M4 12h16M4 18h16', mail:'M3 5h18v14H3V5zm0 0l9 7 9-7',
  calendar:'M4 5h16v16H4V5zm0 5h16M8 2v6m8-6v6', shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4zm-4 10l3 3 5-6', refresh:'M20 7V3m0 4h-4M4 17v4m0-4h4M5 7a8 8 0 0 1 13-2M19 17a8 8 0 0 1-13 2'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.book}"/></svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roles = {admin:'超级管理员',counselor:'研究生辅导员',secretary:'科研秘书',advisor:'导师',student:'研究生'};
const statuses = {pending:'待审核',accepted:'已录取',rejected:'未接收',cancelled:'已撤回',superseded:'已失效',expired:'已截止',approved:'已发布',preparation:'信息准备',round1:'首轮双选中',round1_closed:'首轮已结束',round2:'二轮补选中',completed:'待审核归档',archived:'已归档'};
const grants = {people:'师生信息维护',rules:'规则与轮次配置',matches:'解除与人工调剂',profiles:'导师资料审核',reports:'统计与结果归档',reminders:'进度提醒',quota_adjust:'首轮后名额微调',quota_initial:'年度名额管理',quota_reports:'名额表格导出'};
const S = {user:null,csrf:'',page:'overview',data:{},dashboard:null,notifications:[],search:'',major:'',personRole:'',loading:false,navId:0};
const root = document.getElementById('root');
const dialog = document.getElementById('modal');
let toastTimer;
function toast(message, error=false){const node=document.getElementById('toast');node.textContent=message;node.className=`show${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.className='',5000);}
function detailMessage(data){const d=data.detail ?? data;if(typeof d==='string')return d;if(Array.isArray(d))return d.map(x=>`${x.loc?.slice(1).join('.') || ''}：${x.msg}`).join('\n');return d.message+(d.errors?'\n'+d.errors.map(x=>`第${x.row}行：${x.message}`).join('\n'):'');}
async function api(path, method='GET', data){const headers={};if(method!=='GET')headers['X-CSRF-Token']=S.csrf;const options={method,headers,credentials:'same-origin'};if(data!==undefined){if(data instanceof Blob){options.body=data;headers['Content-Type']='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';}else{headers['Content-Type']='application/json';options.body=JSON.stringify(data);}}const r=await fetch('/api'+path,options);if(!r.ok){let info;try{info=await r.json();}catch{info={detail:`请求失败（${r.status}）`};}if(r.status===401&&S.user){S.user=null;renderLogin();}throw Error(detailMessage(info));}return r.json();}
const date = (v,short=false)=>v?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',...(short?{}:{hour:'2-digit',minute:'2-digit',hour12:false})}).format(new Date(v)):'待配置';
const localInput = v=>{if(!v)return '';const p=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v));return p.replace(' ','T');};
const fromInput = v=>v?`${v}:00+08:00`:'';
const tag = (status,label)=>`<span class="tag ${esc(status)}">${esc(label||statuses[status]||status)}</span>`;
function btn(text,action,id='',variant='',symbol=''){const stage=S.dashboard?.year.stage;let disabled=false;if(stage){const adjustment=['round1_closed','round2','completed'].includes(stage);disabled=(['adjust','matching-plan'].includes(action)&&!adjustment)||(action==='open-round1'&&stage!=='preparation')||(action==='open-round2'&&stage!=='round1_closed')||(action==='close-round'&&stage!==`round${id}`)||(action==='approve-results'&&stage!=='completed')||(action==='archive-results'&&(stage!=='completed'||!S.dashboard.year.approved_at))||(action==='edit-quota'&&(S.user.role==='secretary'?!['preparation','round1'].includes(stage):!adjustment));}return `<button type="button" class="btn ${variant}" data-action="${action}" ${disabled?'disabled':''} ${id!==''?`data-id="${esc(id)}"`:''}>${symbol?icon(symbol):''}${esc(text)}</button>`;}
const empty = message=>`<div class="empty">${icon('book')}${esc(message)}</div>`;
const table = (headers,rows, message='暂无记录')=>rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty(message);
const cellName=(name,sub='')=>`<div class="row"><span class="avatar table-avatar">${esc(name.slice(-2))}</span><div><div class="cell-main">${esc(name)}</div>${sub?`<div class="cell-sub">${esc(sub)}</div>`:''}</div></div>`;
const has = grant=>S.user?.role==='admin'||S.user?.grants?.includes(grant);
const isActive = ()=>{const y=S.dashboard?.year;if(!y||!['round1','round2'].includes(y.stage))return false;const r=y.stage==='round1'?1:2;return new Date(y[`r${r}_start`])<=new Date()&&new Date()<new Date(y[`r${r}_end`]);};
const canChoose = ()=>S.user?.role==='student'&&isActive()&&S.dashboard?.eligible&&!S.dashboard?.match;
const titleMap={overview:'工作台',directory:'导师名录',preferences:'我的志愿',results:'配对结果',intents:'学生意向',profile:'个人资料',people:'师生信息',quotas:'招生名额',reviews:'资料审核',reports:'统计与归档',settings:'双选配置',notifications:'消息中心',audit:'操作日志',history:'历年记录'};

function renderLogin(){root.innerHTML=`<div class="login-screen"><section class="login-art"><div class="brand"><span class="brand-icon">${icon('cap')}</span><div><div class="brand-title">研途</div><div class="brand-sub">GRADUATE MENTOR CONNECT</div></div></div><div class="login-intro"><div class="eyebrow">每一段研究旅程，始于一次双向选择</div><h1>相遇有方向<br>科研有同行</h1><p>连接研究兴趣与学术理想，为研究生与导师搭建透明、有序的双向选择平台。</p><div class="login-features"><span>${icon('shield')}公平透明</span><span>${icon('heart')}双向选择</span><span>${icon('lock')}信息安全</span></div></div><div class="login-art-foot">研究生导师双向选择系统 · 学院专属平台</div></section><section class="login-form-wrap"><div class="login-box"><div class="eyebrow">WELCOME TO YANTU</div><h2>欢迎登录</h2><p class="subtitle">开启你的学术同行之旅</p><form data-form="login"><div class="error-box"></div><label>账号<input name="username" autocomplete="username" placeholder="请输入工号 / 学号" required maxlength="80"></label><label>密码<input name="password" type="password" autocomplete="current-password" placeholder="请输入登录密码" required maxlength="200"></label><button class="btn" type="submit">登录系统 ${icon('arrow')}</button></form><p class="login-small">账号由学院统一创建<br>忘记密码请联系系统管理员</p><details class="demo-panel"><summary>本地演示账号 · 使用示例数据体验</summary><div class="demo-grid">${Object.entries({admin:'管理员',counselor:'辅导员',secretary:'科研秘书',teacher001:'导师',student010:'学生'}).map(([id,name])=>`<button class="demo-chip" data-action="demo" data-id="${id}">${name}</button>`).join('')}</div><p class="subtitle tiny">演示密码：Demo2026!!<br>仅适用于已初始化演示数据的环境。</p></details></div></section></div>`;}

function navItems(){const r=S.user.role;const items=[['overview','dashboard','工作台']];if(r==='student')items.push(['directory','users','导师名录'],['preferences','heart','我的志愿'],['results','check','配对结果'],['history','calendar','历年记录']);if(r==='advisor')items.push(['intents','users','学生意向'],['results','check','录取结果'],['profile','book','个人资料'],['history','calendar','历年记录']);if(['admin','counselor'].includes(r)){if(has('people'))items.push(['people','users',r==='admin'?'账号与师生':'师生信息']);if(has('reports'))items.push(['results','heart','配对结果']);if(r==='counselor'&&has('profiles'))items.push(['reviews','book','资料审核']);if(has('reports'))items.push(['reports','chart','统计与归档']);if(has('rules'))items.push(['settings','settings','双选配置']);}if(r==='secretary'||(r==='counselor'&&has('quota_adjust')))items.push(['quotas','chart','招生名额']);if(r==='admin')items.push(['audit','log','操作日志']);items.push(['notifications','bell','消息中心']);return items;}
function shell(){root.innerHTML=`<aside class="sidebar"><div class="brand"><span class="brand-icon">${icon('cap')}</span><div><div class="brand-title">研途</div><div class="brand-sub">MENTOR CONNECT</div></div></div><div class="college">研究生导师双向选择系统</div><div class="nav-label">工作空间 / WORKSPACE</div><nav class="nav" aria-label="主要导航">${navItems().map(([id,symbol,name])=>`<button class="nav-btn" data-action="nav" data-id="${id}">${icon(symbol)}<span>${name}</span></button>`).join('')}</nav><div class="sidebar-help"><h3 class="small">让选择更有方向</h3><p>了解双选规则与时间安排，<br>共同开启新的研究旅程。</p>${btn('查看双选安排','nav','overview','ghost','arrow')}</div><div class="profile-mini spread"><div class="row"><span class="avatar">${esc(S.user.name.slice(-2))}</span><div><div class="profile-name">${esc(S.user.name)}</div><div class="profile-role">${roles[S.user.role]}</div></div></div><button class="icon-btn" data-action="password" title="修改密码" aria-label="修改密码">${icon('settings')}</button></div></aside><main class="main"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="展开导航">${icon('menu')}</button><div class="breadcrumbs">工作空间 <span>/</span><strong id="crumb">工作台</strong></div><div class="top-right"><span class="year-pill"><span class="dot"></span><span id="year-name">学年信息</span></span><span class="tiny muted">${roles[S.user.role]}</span><button class="icon-btn notification-button" data-action="nav" data-id="notifications" aria-label="消息中心">${icon('bell')}<span id="unread-indicator"></span></button><button class="icon-btn" data-action="logout" title="退出登录" aria-label="退出登录">${icon('logout')}</button></div></header><div class="content" id="content"></div></main>`;}

async function navigate(page=S.page){if(!S.user)return;const id=++S.navId;S.page=page;S.search='';S.major='';document.querySelector('.sidebar')?.classList.remove('open');document.querySelectorAll('.nav-btn').forEach(b=>{b.classList.toggle('active',b.dataset.id===page);b.setAttribute('aria-current',b.dataset.id===page?'page':'false');});document.getElementById('crumb').textContent=titleMap[page];document.getElementById('content').innerHTML=empty('正在加载…');try{const dashboard=await api('/dashboard');let data={};if(page==='directory'||page==='quotas')data.advisors=await api('/advisors');if(page==='preferences'||page==='intents')data.applications=await api('/applications'+(page==='intents'?'?sort=time':''));if(page==='people')data.users=await api('/users');if(page==='results'){data.matches=await api('/matches');if(S.user.role==='counselor'&&has('people'))data.users=await api('/users?role=student');}if(page==='profile')data.profile=await api('/profile');if(page==='reviews')data.requests=await api('/profile-requests');if(page==='settings')data.years=await api('/years');if(page==='audit')data.logs=await api('/audit');if(page==='history')data.history=await api('/history');if(page==='overview'&&['admin','counselor'].includes(S.user.role)&&has('reports'))data.matches=await api('/matches');const notifications=await api('/notifications');if(id!==S.navId||!S.user)return;S.dashboard=dashboard;S.notifications=notifications;S.data=data;document.getElementById('year-name').textContent=dashboard.year.name;renderPage();updateUnread();}catch(e){if(id===S.navId&&S.user){document.getElementById('content').innerHTML=`<div class="panel"><div class="panel-body">${empty(e.message)}${btn('重试','reload','','secondary','refresh')}${S.user.role==='admin'?btn('创建首个学年','new-year','','','plus'):''}</div></div>`;}}}

function head(title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">GRADUATE MENTOR CONNECT</div><h1>${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div><div class="row wrap">${actions}</div></div>`;}
function panel(title,body,actions='',caption=''){return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2>${caption?`<p class="panel-caption">${esc(caption)}</p>`:''}</div><div class="row wrap">${actions}</div></div>${body}</section>`;}
function metric(label,value,suffix,foot,symbol){return `<div class="metric"><div class="metric-label">${label}<span class="metric-icon">${icon(symbol)}</span></div><div class="metric-value">${esc(value)}<small>${suffix}</small></div><div class="metric-foot"><span class="positive">${icon('check')}</span>${esc(foot)}</div></div>`;}
function timeline(){const y=S.dashboard.year,stage=y.stage;const current={preparation:0,round1:1,round1_closed:2,round2:3,completed:4,archived:5}[stage];const steps=[['信息初始化','师生信息与年度招生名额准备'],['首轮志愿填报',`${date(y.r1_start)} — ${date(y.r1_end)}`],['首轮结果锁定','已配对结果锁定，辅导员调整名额'],['第二轮专项补选',y.r2_start?`${date(y.r2_start)} — ${date(y.r2_end)}`:'由辅导员手动开启，仅限未匹配学生'],['结果审核与归档',stage==='archived'?'本学年已归档，结果只读':'最终结果统一审核，报表留存归档']];return `<div class="panel-body">${steps.map(([name,note],i)=>`<div class="stage-step ${i<current?'done':i===current?'current':''}"><span class="step-circle">${i<current?'✓':String(i+1).padStart(2,'0')}</span><div class="step-content"><h3>${name}</h3><p>${esc(note)}</p>${i===current?'<span class="stage-hint">当前阶段</span>':''}</div></div>`).join('')}</div>`;}
function notificationList(items,limit=100){return items.length?items.slice(0,limit).map(n=>`<article class="notification-item ${n.read?'':'unread'}"><span class="notification-icon">${icon('bell')}</span><div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><div class="notification-time">${date(n.created_at)}</div></div></article>`).join(''):empty('暂时没有消息');}
function stageBanner(){const y=S.dashboard.year;let message=`当前为「${statuses[y.stage]}」阶段，请按学院安排完成操作。`;if(y.stage==='round1')message=`首轮截止时间 ${date(y.r1_end)}（北京时间）。已配对结果自动锁定，二轮由辅导员手动开启。`;if(y.stage==='round2')message=`二轮截止时间 ${date(y.r2_end)}（北京时间）。仅首轮未匹配学生可参与补选。`;if(y.stage==='archived')message='本学年数据已归档，配对结果保持只读。';return `<div class="banner"><div class="row"><span class="banner-mark">${icon('info')}</span><div><h3>${esc(y.name)} · ${statuses[y.stage]}</h3><p>${esc(message)}</p></div></div>${tag(y.stage)}</div>`;}
function majorProgress(){const rows=S.dashboard.majors||[];return `<div class="panel-body">${rows.map(m=>`<div class="progress-major"><div class="spread"><span>${esc(m.major)}</span><small>${m.matched} / ${m.students} 人已配对</small></div><progress value="${m.matched}" max="${m.students||1}" aria-label="${esc(m.major)}配对进度"></progress></div>`).join('')||empty('暂无专业数据')}</div>`;}
function renderOverview(){const d=S.dashboard,r=S.user.role;const dateText=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date());let actions='';if(['admin','counselor'].includes(r)&&has('reports'))actions=btn('导出双选报表','export','results','secondary','download')+btn('查看配对结果','nav','results','','arrow');if(r==='student')actions=btn('浏览导师','nav','directory','','arrow');if(r==='advisor')actions=btn('审核学生意向','nav','intents','','arrow');if(r==='secretary')actions=btn('管理招生名额','nav','quotas','','arrow');let metrics='';if(r==='student'){metrics=metric('当前填报志愿',d.pending,'项',`本届最多 ${d.year.wish_limit} 项有效志愿`,'heart')+metric('配对状态',d.match?'已配对':'未配对','',d.match?'配对结果已锁定':'等待导师审核确认','check')+metric('本轮参与资格',d.match?'已完成':d.eligible?'可参与':'不可参与','',isActive()?'填报通道在时间窗口内':'请留意开放时间','users')+metric('未读消息',S.notifications.filter(n=>!n.read).length,'条','及时了解双选最新进展','bell');}else if(r==='advisor'){metrics=metric('年度招生名额',d.total,'人','由学院统一配置','users')+metric('已录取学生',d.total-d.remaining,'人','确认后自动锁定配对','check')+metric('剩余招生名额',d.remaining,'人','录取与调剂实时更新','chart')+metric('待审核意向',d.pending,'项','仅展示填报自己的学生','heart');}else{const rate=d.students?Math.round(d.matched/d.students*100):0;metrics=metric('本届研究生',d.students,'人','学年学生信息独立管理','users')+metric('参与导师',d.advisors,'位','导师名录长期维护','cap')+metric('已配对学生',d.matched,'人',`另有 ${d.students-d.matched} 人待配对`,'heart')+metric('双选完成率',rate,'%',`共 ${d.total} 个年度招生名额`,'chart');}const left = ['admin','counselor'].includes(r)?panel('最新配对动态',matchTable((S.data.matches||[]).slice(0,5),false),has('reports')?btn('查看全部','nav','results','ghost','arrow'):'','师生双向选择确认后，配对结果自动锁定'):r==='student'?panel('我的双选进度',`<div class="panel-body">${d.match?`<div class="row"><span class="avatar advisor-avatar">${esc(d.match.advisor_name.slice(-2))}</span><div><div class="section-label">已确认导师</div><h2>${esc(d.match.advisor_name)}</h2><p class="subtitle">${esc(d.match.advisor_major)} · 结果已锁定</p></div></div>`:`<h2>在这里，找到学术同行者</h2><p class="subtitle">了解导师的研究方向，按照兴趣提交志愿。导师确认后，配对即生效。</p><div class="form-actions">${btn('查看我的志愿','nav','preferences','secondary')}${btn('探索导师名录','nav','directory','','arrow')}</div>`}</div>`):r==='advisor'?panel('招生工作提醒',`<div class="panel-body"><h2>${d.pending?`${d.pending} 项学生意向等待审核`:'期待新的研究同行者'}</h2><p class="subtitle">请在本轮截止前完成意向审核。确认接收将扣减招生名额并锁定配对；拒绝将释放学生的志愿填报权限。</p><div class="form-actions">${btn('个人公示资料','nav','profile','secondary')}${btn('进入学生意向','nav','intents','','arrow')}</div></div>`):panel('年度名额工作',`<div class="panel-body"><h2>有序配置，精准管控</h2><p class="subtitle">下载导师名单，填写招生名额后批量导入。系统会实时计算剩余名额，避免超额招生。</p><div class="form-actions">${btn('下载名额表格','export','quotas','secondary','download')}${btn('配置招生名额','nav','quotas','','arrow')}</div></div>`);return head(`你好，${S.user.name}${['admin','counselor','secretary'].includes(r)?'':'同学'.repeat(r==='student')}`,`${dateText} · 每一次双向选择，都是新旅程的起点。`,actions)+stageBanner()+`<div class="metrics">${metrics}</div><div class="dashboard-grid"><div class="stack">${left}${d.majors?panel('各专业双选进度',majorProgress()):panel('学院通知',`<div class="panel-body">${notificationList(S.notifications,3)}</div>`,btn('全部消息','nav','notifications','ghost','arrow'))}</div><div class="stack">${panel('双选流程',timeline(),tag(d.year.stage))}${d.majors?panel('最新通知',`<div class="panel-body">${notificationList(S.notifications,3)}</div>`,btn('全部消息','nav','notifications','ghost','arrow')):''}</div></div>`;}

function directoryCards(){const rows=(S.data.advisors||[]).filter(a=>(!S.search||`${a.name} ${a.direction} ${a.major}`.toLowerCase().includes(S.search.toLowerCase()))&&(!S.major||a.major===S.major));return rows.length?rows.map(a=>`<article class="advisor-card"><div class="row"><span class="avatar advisor-avatar">${esc(a.name.slice(-2))}</span><div><h2>${esc(a.name)}</h2><span class="tiny muted">${esc(a.title)} · ${esc(a.major)}</span></div></div><div><div class="section-label">研究方向 / RESEARCH</div><p class="card-direction">${esc(a.direction||'暂未填写研究方向')}</p></div><p class="card-bio">${esc(a.bio||'导师尚未填写个人简介。')}</p><div class="card-bottom">${btn('查看完整资料','advisor-detail',a.id,'ghost','arrow')}${canChoose()?btn('填报志愿','choose',a.id,'secondary small-btn','plus'):tag('success',S.dashboard.match?'已完成双选':'公示信息')}</div></article>`).join(''):empty('没有符合条件的导师');}
function renderDirectory(){return head('寻找你的学术同行者','了解研究方向，让兴趣与选择相遇。导师资料由学院审核后公示。')+`<div class="directory-tools"><div class="search">${icon('search')}<input id="search" placeholder="搜索导师姓名、研究方向或专业" aria-label="搜索导师"></div><select id="major-filter" aria-label="筛选专业"><option value="">全部专业</option>${[...new Set(S.data.advisors.map(a=>a.major))].map(m=>`<option>${esc(m)}</option>`).join('')}</select><span class="tiny muted">按专业与研究兴趣选择</span></div><div class="directory-grid" id="directory-list">${directoryCards()}</div>`;}

function applicationTable(rows,intents=false){return table(intents?['学生信息','报考专业 / 成绩','志愿','提交时间','审核状态','操作']:['意向导师','志愿顺序','轮次','提交时间','当前状态','操作'],rows.map(a=>`<tr><td>${intents?cellName(a.student_name,a.student_no):`<div class="cell-main">${esc(a.advisor_name)}</div><div class="cell-sub">${esc(a.student_major)}</div>`}</td><td>${intents?`${esc(a.student_major)}<div class="cell-sub">入学成绩 ${a.score}</div>`:`第 ${a.rank} 志愿`}</td><td>${intents?`第 ${a.rank} 志愿`:`第 ${a.round} 轮`}</td><td class="nowrap">${date(a.created_at)}</td><td>${tag(a.status)}${a.note?`<div class="cell-sub">${esc(a.note)}</div>`:''}</td><td><div class="row">${a.status==='pending'&&isActive()?(intents?btn('确认接收','review-intent',a.id,'small-btn','check')+btn('拒绝','reject-intent',a.id,'ghost'):canChoose()?btn('修改','edit-choice',a.id,'ghost','edit')+btn('撤回','cancel-choice',a.id,'ghost'):''):`<span class="tiny muted">${icon('lock')} 已锁定</span>`}</div></td></tr>`),'暂无志愿记录');}
function renderPreferences(){const d=S.dashboard;return head('我的志愿','按照研究兴趣填报意向，导师拒绝后可重新选择。',canChoose()?btn('新增志愿','choose','','','plus'):'')+stageBanner()+`<div class="notice-block">本届最多可保留 ${d.year.wish_limit} 个待审核志愿。导师确认接收后，其他待审核志愿自动失效，配对结果锁定。截止后不能新增、修改或撤回。</div>`+panel('志愿填报记录',applicationTable(S.data.applications),tag('pending',`${d.pending} 项待审核`));}
function renderIntents(){return head('学生意向审核','仅展示填报自己的学生。确认接收后立即生效，请谨慎审核。',btn('导出录取明细','export','personal','secondary','download'))+stageBanner()+panel('意向学生',`<div class="toolbar"><span class="tiny muted">按成绩与填报时间择优审核</span><select id="intent-sort" class="input-inline" aria-label="排序方式"><option value="time">填报时间</option><option value="score">成绩优先</option></select></div><div id="intent-table">${applicationTable(S.data.applications,true)}</div>`,tag('pending',`${S.dashboard.pending} 项待审核`));}
function matchTable(rows,actions=true){return table(['学生信息','专业','配对导师','配对方式','配对时间',...(actions&&S.user.role==='counselor'&&has('matches')?['操作']:[])],rows.map(m=>`<tr><td>${cellName(m.student_name,m.student_no)}</td><td>${esc(m.student_major)}</td><td><div class="cell-main">${esc(m.advisor_name)}</div><div class="cell-sub">${tag('success','结果锁定')}</div></td><td><span class="tiny muted">${m.source==='counselor'?'辅导员调剂':`第${m.round}轮双选`}</span></td><td class="nowrap">${date(m.created_at)}</td>${actions&&S.user.role==='counselor'&&has('matches')?`<td>${btn('调整配对','adjust',m.student_id,'ghost','edit')}</td>`:''}</tr>`),'暂无已配对结果');}
function renderResults(){const r=S.user.role,d=S.dashboard;let body;if(r==='student'){const m=S.data.matches[0];body=m?`<div class="result-card"><span class="avatar advisor-avatar">${esc(m.advisor_name.slice(-2))}</span><div><div class="eyebrow">你的学术同行者</div><h2>${esc(m.advisor_name)}</h2><p>${esc(m.advisor_major)} · 第${m.round}轮确认<br>配对时间 ${date(m.created_at)}</p></div>${tag('success','已确认并锁定')}</div><div class="notice-block">配对结果已生效。如需处理特殊改选或退选，请联系研究生辅导员。</div>`:panel('等待双向选择',`<div class="panel-body">${empty('你尚未匹配导师，请留意填报窗口和审核进度。')}${btn('查看我的志愿','nav','preferences','','arrow')}</div>`);}else{body=panel(r==='advisor'?'我的录取学生':'已确认配对结果',matchTable(S.data.matches),tag('success',`${S.data.matches.length} 人已配对`));if(r==='counselor'&&has('matches')&&S.data.users){const paired=new Set(S.data.matches.map(m=>m.student_id));const unmatched=S.data.users.filter(x=>x.enabled&&!paired.has(x.id));body+=`<div class="stack spacer">${panel('未匹配学生',table(['学生','专业','成绩','操作'],unmatched.map(s=>`<tr><td>${cellName(s.name,s.username)}</td><td>${esc(s.major)}</td><td>${s.score}</td><td>${btn('人工调剂','adjust',s.id,'ghost','edit')}</td></tr>`),'本届学生均已匹配'),tag('pending',`${unmatched.length} 人`))}</div>`;}}const actions=r==='advisor'?btn('导出个人明细','export','personal','secondary','download'):['admin','counselor'].includes(r)?btn('导出配对总表','export','results','secondary','download'):'';return head(r==='student'?'我的配对结果':'师生配对结果','师生配对确认后自动锁定，特殊调整由研究生辅导员处理。',actions+(r==='counselor'&&has('matches')?btn('生成调剂建议','matching-plan','','','heart'):''))+body;}

function userRows(){const users=S.data.users.filter(u=>(!S.personRole||u.role===S.personRole)&&(!S.search||`${u.name} ${u.username} ${u.major}`.includes(S.search)));return table(['姓名 / 账号','角色','专业 / 职称','状态','操作'],users.map(u=>`<tr><td>${cellName(u.name,u.username)}</td><td>${roles[u.role]}</td><td>${esc(u.major||'—')}<div class="cell-sub">${esc(u.title)}</div></td><td>${tag(u.enabled?'success':'danger',u.enabled?'正常':'已停用')}</td><td><div class="row wrap">${btn('编辑','edit-user',u.id,'ghost','edit')}${S.user.role==='admin'&&['counselor','secretary'].includes(u.role)?btn('岗位权限','grants',u.id,'ghost'):''}${S.user.role==='admin'?btn('重置密码','reset-password',u.id,'ghost'):''}</div></td></tr>`),'暂无符合条件的账号');}
function renderPeople(){const options=S.user.role==='admin'?['','admin','counselor','secretary','advisor','student']:['','student','advisor'];return head(S.user.role==='admin'?'账号与师生管理':'师生基础信息','导师名录长期维护，研究生信息按学年独立管理。',btn('Excel 导入','import-people','','secondary','upload')+btn('新增账号','add-user','','','plus'))+`<div class="tabs">${options.map(r=>`<button class="tab ${S.personRole===r?'active':''}" data-action="people-tab" data-id="${r}">${r?roles[r]:'全部账号'}</button>`).join('')}</div>`+panel('本院人员名录',`<div class="toolbar"><div class="search">${icon('search')}<input id="search" placeholder="搜索姓名、账号或专业" aria-label="搜索账号"></div><span class="tiny muted">${S.data.users.length} 个账号 · ${esc(S.dashboard.year.name)}</span></div><div id="people-table">${userRows()}</div>`);}
function quotaRows(){return table(['导师','专业 / 职称','年度名额','已录取','剩余名额','操作'],S.data.advisors.filter(a=>!S.search||`${a.name} ${a.major} ${a.username}`.includes(S.search)).map(a=>`<tr><td>${cellName(a.name,a.username)}</td><td>${esc(a.major)}<div class="cell-sub">${esc(a.title)}</div></td><td>${a.total}</td><td>${a.matched}</td><td>${tag(a.remaining>0?'success':'pending',`${a.remaining} 人`)}</td><td>${btn('调整名额','edit-quota',a.id,'ghost','edit')}</td></tr>`));}
function renderQuotas(){return head('导师招生名额','剩余名额由系统根据配对人数实时计算，无需人工更新。',btn('下载填报名单','export','quotas','secondary','download')+btn('批量导入名额','import','quotas','','upload'))+`<div class="notice-block">${S.user.role==='secretary'?'科研秘书负责首轮前与首轮期间的年度名额配置。首轮结束后的名额微调由辅导员处理。':'辅导员负责首轮结束后的名额微调。'} 名额不能低于已录取人数；年度名额为 0 的导师不在学生端展示。</div>`+panel('年度招生名额',`<div class="toolbar"><div class="search">${icon('search')}<input id="search" placeholder="搜索导师姓名、工号或专业" aria-label="搜索导师名额"></div>${tag('success',`总名额 ${S.dashboard.total}`)}</div><div id="quota-table">${quotaRows()}</div>`);}

function profileFields(p){return ['bio','direction','projects','achievements','notice'].map(k=>`<label class="full">${{bio:'个人简介',direction:'研究方向',projects:'科研项目',achievements:'科研成果',notice:'招生说明'}[k]}<textarea name="${k}" maxlength="${['bio','projects','achievements'].includes(k)?5000:2000}" placeholder="请填写${{bio:'个人简介',direction:'研究方向',projects:'科研项目',achievements:'科研成果',notice:'招生说明'}[k]}">${esc(p[k]||'')}</textarea></label>`).join('');}
function renderProfile(){const p=S.data.profile;const latest=p.requests[0];const draft=latest&&['pending','rejected'].includes(latest.status)?latest.content:p.published;return head('个人公示资料','更新研究方向与科研成果，审核通过后向学生公示。')+`<div class="notice-block">修改不会立即覆盖公示内容，需经辅导员审核后生效。${latest?` 最近一次提交：${statuses[latest.status]}${latest.review_note?'；'+esc(latest.review_note):''}`:''}</div>`+panel('编辑个人资料',`<div class="panel-body"><form data-form="profile"><div class="error-box"></div><div class="form-grid">${profileFields(draft)}</div><div class="form-actions"><button class="btn" type="submit">提交辅导员审核 ${icon('arrow')}</button></div></form></div>`)+`<div class="spacer">${panel('资料提交历史',table(['提交时间','状态','审核说明'],p.requests.map(x=>`<tr><td>${date(x.created_at)}</td><td>${tag(x.status)}</td><td>${esc(x.review_note||'—')}</td></tr>`)))}</div>`;}
function renderReviews(){return head('导师资料审核','审核通过后自动更新导师公示资料；新提交会替代旧的待审核版本。')+panel('资料审核列表',table(['导师','研究方向','提交时间','状态','操作'],S.data.requests.map(p=>`<tr><td>${esc(p.advisor_name)}</td><td>${esc(p.content.direction||'未填写')}</td><td>${date(p.created_at)}</td><td>${tag(p.status)}</td><td>${btn(p.status==='pending'?'查看并审核':'查看内容','review-profile',p.id,'ghost','book')}</td></tr>`)));}
function renderReports(){const d=S.dashboard,y=d.year;return head('双选统计与归档','查看完成情况，审核最终结果，导出标准 Excel 报表。',btn('导出全套报表','export','results','','download'))+`<div class="metrics">${metric('本届学生',d.students,'人','按学年独立统计','users')}${metric('成功配对',d.matched,'人',`配对率 ${d.students?Math.round(d.matched/d.students*100):0}%`,'check')}${metric('未匹配学生',d.students-d.matched,'人','关注补选与调剂工作','heart')}${metric('剩余名额',d.total-d.matched,'人','导师名额实时计算','chart')}</div><div class="settings-grid">${panel('各专业配对进度',majorProgress())}${panel('结果审核与归档',`<div class="panel-body stack"><p class="small muted">当前状态：${tag(y.stage)}</p><p class="subtitle">导出包含师生配对总表、分专业明细、导师招生汇总与未匹配学生表。请在二轮关闭后完成审核，归档后本学年配对结果不可更改。</p>${y.approved_at?`<p class="small success">${icon('check')} 最终结果已审核 · ${date(y.approved_at)}</p>`:''}${S.user.role==='counselor'?`<div class="row wrap">${btn('审核最终结果','approve-results','','secondary','check')}${btn('归档本学年','archive-results','','','lock')}</div>`:''}<label>导出指定专业<select id="report-major"><option value="">全部专业</option>${(d.majors||[]).map(m=>`<option>${esc(m.major)}</option>`).join('')}</select></label>${btn('导出专业明细','export-major','','secondary','download')}</div>`)}</div>${S.user.role==='counselor'&&has('reminders')?`<div class="spacer">${panel('双选进度提醒',`<div class="panel-body"><p class="subtitle">向未匹配学生或仍有待审核意向的导师发送站内工作提醒。</p><div class="form-actions">${btn('发送提醒','reminder','','secondary','bell')}</div></div>`)}</div>`:''}`;}
function renderSettings(){const y=S.dashboard.year;const counselor=S.user.role==='counselor';return head('双选规则与学年配置','时间均为北京时间。首轮结束后不会自动开启二轮。',S.user.role==='admin'?btn('创建新学年','new-year','','','plus'):'')+stageBanner()+`<div class="settings-grid">${panel('首轮规则配置',`<div class="panel-body"><form data-form="rules"><div class="error-box"></div><div class="form-grid"><label class="full">学生有效志愿上限<input type="number" name="wish_limit" min="1" max="10" value="${y.wish_limit}" required></label><label>首轮开始时间<input type="datetime-local" name="start" value="${localInput(y.r1_start)}" required></label><label>首轮截止时间<input type="datetime-local" name="end" value="${localInput(y.r1_end)}" required></label><label class="full">专业招生上限（每行：专业=名额）<textarea name="major_caps" placeholder="计算机科学与技术=20\n软件工程=20">${esc(Object.entries(y.major_caps).map(([k,v])=>`${k}=${v}`).join('\n'))}</textarea><span class="field-hint">留空表示不设专业总额上限；导师名额合计不能超过对应专业上限。</span></label></div><div class="form-actions"><button class="btn" ${y.stage!=='preparation'?'disabled':''}>保存规则</button></div></form></div>`) }${panel('轮次流程管控',`<div class="panel-body phase-actions">${counselor?`<div class="phase-action"><h3>01 · 首轮双选</h3><p>完成师生信息、年度名额与规则配置后开启。截止时间到达后自动关闭。</p><div class="row wrap">${btn('开启首轮','open-round1','','','arrow')}${btn('提前关闭首轮','close-round',1,'secondary','lock')}</div></div><div class="phase-action"><h3>02 · 第二轮专项补选</h3><p>首轮结束后调整名额，再手动开启补选。仅首轮未匹配学生可参加。</p><div class="row wrap">${btn('配置并开启二轮','open-round2','','','arrow')}${btn('提前关闭二轮','close-round',2,'secondary','lock')}</div></div>`:`<p class="subtitle">超级管理员可初始化规则。首轮开启、二轮补选与流程关闭由研究生辅导员负责。</p>`}<div class="phase-action"><h3>03 · 审核与归档</h3><p>二轮关闭后，辅导员审核最终结果并归档。归档后可创建下一学年。</p>${btn('查看统计与归档','nav','reports','secondary','chart')}</div></div>`)}</div>${S.user.role==='admin'?`<div class="spacer">${panel('学年管理',table(['学年','状态','当前学年','操作'],S.data.years.map(a=>`<tr><td>${esc(a.name)}</td><td>${tag(a.stage)}</td><td>${a.current?tag('success','当前使用'):'—'}</td><td>${!a.current?btn('切换查看','activate-year',a.id,'ghost'):'—'}</td></tr>`)))}</div>`:''}`;}
function renderNotifications(){return head('消息中心','查看双选安排、意向审核与配对结果通知。',btn('全部标为已读','read-notifications','','secondary','check'))+panel('我的站内消息',`<div class="panel-body">${notificationList(S.notifications)}</div>`,tag('pending',`${S.notifications.filter(n=>!n.read).length} 条未读`));}
function renderAudit(){return head('操作日志','关键操作只追加留存，支持哈希链完整性检查。',btn('验证日志完整性','verify-audit','','secondary','shield'))+panel('最近 300 条操作记录',table(['时间','操作人','操作类型','详情'],S.data.logs.map(l=>`<tr><td class="nowrap">${date(l.created_at)}</td><td>${esc(l.actor_name||'系统')}</td><td>${esc(l.action)}</td><td class="audit-detail">${esc(JSON.stringify(l.detail))}</td></tr>`)));}
function renderHistory(){return head('历年配对记录','查看自己的历年双选结果与招生记录。')+panel('历史记录',table(['学年','学生','专业','导师','配对时间'],S.data.history.map(m=>`<tr><td>${esc(m.year_name)}</td><td>${cellName(m.student_name,m.student_no)}</td><td>${esc(m.student_major)}</td><td>${esc(m.advisor_name)}</td><td>${date(m.created_at)}</td></tr>`)));}
function renderPage(){const renderers={overview:renderOverview,directory:renderDirectory,preferences:renderPreferences,intents:renderIntents,results:renderResults,people:renderPeople,quotas:renderQuotas,profile:renderProfile,reviews:renderReviews,reports:renderReports,settings:renderSettings,notifications:renderNotifications,audit:renderAudit,history:renderHistory};document.getElementById('content').innerHTML=(renderers[S.page]||renderOverview)()+`<footer class="footer"><span>研途 · 研究生导师双向选择系统</span><span>学院专属平台 &nbsp; / &nbsp; 公平 · 透明 · 有序</span></footer>`;}
function updateUnread(){const n=S.notifications.filter(x=>!x.read).length;const el=document.getElementById('unread-indicator');if(el)el.className=n?'unread-dot':'';}

function modal(title,body){document.getElementById('modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function modalForm(title,type,fields,submit='保存',intro='',id=''){modal(title,`<form data-form="${type}" data-id="${esc(id)}"><div class="error-box"></div>${intro?`<p class="subtitle">${esc(intro)}</p>`:''}<div class="form-grid">${fields}</div><div class="form-actions">${btn('取消','close-modal','','secondary')}<button class="btn" type="submit">${esc(submit)}</button></div></form>`);}
function confirmation(title,message,type,id='',submit='确认'){modalForm(title,type,'',submit,message,id);}
async function choiceModal(id='',edit=false){const advisors=S.data.advisors||await api('/advisors');S.data.choiceAdvisors=advisors;const original=edit?S.data.applications.find(a=>a.id===Number(id)):null;const selected=original?.advisor_id || Number(id);const occupied=new Set((S.data.applications||[]).filter(x=>x.status==='pending'&&x.id!==original?.id).map(x=>x.rank));const options=Array.from({length:S.dashboard.year.wish_limit},(_,i)=>i+1).filter(n=>!occupied.has(n));modalForm(edit?'修改意向志愿':'新增意向志愿',edit?'edit-choice':'choice',`<label class="full">意向导师<select name="advisor_id" required>${advisors.map(a=>`<option value="${a.id}" ${selected===a.id?'selected':''}>${esc(a.name)} · ${esc(a.direction||a.major)}</option>`).join('')}</select></label><label class="full">志愿顺序<select name="rank" required>${options.map(n=>`<option value="${n}" ${original?.rank===n?'selected':''}>第 ${n} 志愿</option>`).join('')}</select></label>`,edit?'保存修改':'提交志愿','提交后进入导师审核流程。导师确认即锁定配对。',edit?id:'');}
function userModal(id=''){const p=id?S.data.users.find(x=>x.id===Number(id)):null;const admin=S.user.role==='admin';modalForm(p?'编辑基础信息':'新增账号',p?'edit-user':'user',`${p?'':`<label>账号 / 工号 / 学号<input name="username" pattern="[A-Za-z0-9_.-]+" maxlength="80" required autocomplete="off"></label><label>角色<select name="role">${(admin?Object.keys(roles):['student','advisor']).map(r=>`<option value="${r}" ${r==='student'?'selected':''}>${roles[r]}</option>`).join('')}</select></label><label class="full">初始密码<input name="password" type="password" minlength="10" maxlength="200" required autocomplete="new-password"><span class="field-hint">至少10位，请通过安全渠道告知本人。</span></label>`}<label>姓名<input name="name" value="${esc(p?.name)}" maxlength="80" required></label><label>专业<input name="major" value="${esc(p?.major)}" maxlength="100" placeholder="管理岗可留空"></label><label>职称<input name="title" value="${esc(p?.title)}" maxlength="100"></label><label>成绩<input name="score" type="number" min="0" max="1000" step="0.01" value="${p?.score||0}"></label>${p?`<label class="check-label full"><input name="enabled" type="checkbox" ${p.enabled?'checked':''}>账号启用（取消勾选即停用 / 解绑）</label>`:''}`,'保存',p?'工号与角色保持固定。停用账号将立即使其登录会话失效。':'学生归属当前学年；导师基础信息长期保存。',id);}
async function adjustModal(sid){let people=S.data.users||await api('/users?role=student');const student=people.find(s=>s.id===Number(sid));const matched=S.data.matches.find(m=>m.student_id===Number(sid));const suggestions=await api('/matching-suggestions/'+sid);modalForm('特殊调整 / 人工调剂','adjust',`<input name="student_id" type="hidden" value="${esc(sid)}"><label class="full">学生<input value="${esc(student?.name||matched?.student_name||'')}${student?' · '+esc(student.major):''}" disabled></label><label class="full">目标导师<select name="advisor_id"><option value="">解除当前配对（不另配导师）</option>${suggestions.map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(a.major)}${a.same_major?' · 同专业优先':''} · 剩余${a.remaining}人</option>`).join('')}</select></label><label class="full">调整原因<textarea name="reason" minlength="2" maxlength="1000" placeholder="请填写特殊调整原因，操作将全程留痕" required></textarea></label>`,'确认调整','仅辅导员可操作。调整会更新相关导师名额，并通知师生。');}
function importModal(kind){modalForm('Excel 批量导入','import',`<input type="hidden" name="kind" value="${kind}"><label class="full">标准 Excel 文件<input type="file" name="file" accept=".xlsx" required><span class="field-hint">最多5MB、2000行。全部校验通过后才写入；有错误则整批不写入。</span></label><div class="full">${btn('下载标准模板','export',kind==='quotas'?'quotas':`${kind}-template`,'secondary','download')}</div>`,'开始导入','请保留模板表头。师生导入仅新增，已有账号不会被覆盖。');}
async function download(kind,major=''){const r=await fetch(`/api/export/${kind}${major?'?major='+encodeURIComponent(major):''}`,{credentials:'same-origin'});if(!r.ok)throw Error(detailMessage(await r.json()));const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=(r.headers.get('content-disposition')?.match(/filename="([^"]+)"/)||[])[1]||`${kind}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Excel 文件已导出');}

document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id||'';try{switch(action){
  case 'nav':await navigate(id);break;
  case 'menu':document.querySelector('.sidebar').classList.toggle('open');break;
  case 'reload':await navigate();break;
  case 'demo':{const f=document.querySelector('[data-form="login"]');f.elements.username.value=id;f.elements.password.value='Demo2026!!';f.elements.username.focus();break;}
  case 'close-modal':dialog.close();break;
  case 'logout':await api('/logout','POST');S.user=null;S.csrf='';dialog.close();renderLogin();break;
  case 'password':modalForm('修改登录密码','password','<label class="full">当前密码<input name="old_password" type="password" required autocomplete="current-password"></label><label class="full">新密码<input name="new_password" type="password" minlength="10" maxlength="200" required autocomplete="new-password"></label>','修改并重新登录','修改成功后所有已登录会话失效。');break;
  case 'advisor-detail':{const a=S.data.advisors.find(x=>x.id===Number(id));modal(a.name,`<div class="row"><span class="avatar advisor-avatar">${esc(a.name.slice(-2))}</span><div><h2>${esc(a.name)}</h2><p class="subtitle">${esc(a.major)} · ${esc(a.title)}</p></div></div>${[['direction','研究方向'],['bio','个人简介'],['projects','科研项目'],['achievements','科研成果'],['notice','招生说明']].map(([k,t])=>`<section class="detail-section"><h3>${t}</h3><p>${esc(a[k]||'暂未填写')}</p></section>`).join('')}<div class="form-actions">${canChoose()?btn('选择这位导师','choose',id,'','heart'):btn('关闭','close-modal','','secondary')}</div>`);break;}
  case 'choose':await choiceModal(id);break;
  case 'edit-choice':await choiceModal(id,true);break;
  case 'cancel-choice':confirmation('撤回志愿','撤回后可以在本轮时间内重新提交。','cancel-choice',id,'确认撤回');break;
  case 'review-intent':case 'reject-intent':{const accept=action==='review-intent';const a=S.data.applications.find(x=>x.id===Number(id));modalForm(accept?'确认接收学生':'拒绝本条意向','review-intent',`<input type="hidden" name="decision" value="${accept?'accept':'reject'}"><label class="full">审核说明<textarea name="note" maxlength="1000" placeholder="可填写审核说明${accept?'':'或拒绝原因'}"></textarea></label>`,accept?'确认接收并锁定':'确认拒绝',`${a.student_name} · ${a.student_major} · 成绩 ${a.score}。${accept?'确认后立即扣减名额，学生与导师均不能撤销。':'拒绝后学生将恢复填报权限。'}`,id);break;}
  case 'people-tab':S.personRole=id;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.id===id));document.getElementById('people-table').innerHTML=userRows();break;
  case 'add-user':userModal();break;
  case 'edit-user':userModal(id);break;
  case 'grants':{const p=S.data.users.find(x=>x.id===Number(id));const keys=p.role==='secretary'?['quota_initial','quota_reports']:['people','rules','matches','profiles','reports','reminders','quota_adjust'];modalForm('岗位专项权限','grants',keys.map(g=>`<label class="check-label full"><input type="checkbox" name="grants" value="${g}" ${p.grants.includes(g)?'checked':''}>${grants[g]}</label>`).join(''),'保存权限',`${p.name} · ${roles[p.role]}。权限仅能在本岗位职责范围内调整。`,id);break;}
  case 'reset-password':modalForm('重置账号密码','reset-password','<label class="full">新密码<input name="password" type="password" minlength="10" maxlength="200" required autocomplete="new-password"></label>','重置密码','重置后该账号所有会话立即失效，请通过安全渠道告知本人。',id);break;
  case 'edit-quota':{const a=S.data.advisors.find(x=>x.id===Number(id));modalForm('调整年度招生名额','quota',`<label class="full">招生名额<input name="total" type="number" value="${a.total}" min="${a.matched}" max="10000" required></label>`,'保存名额',`${a.name} · 已录取 ${a.matched} 人。名额不能低于已录取人数。`,id);break;}
  case 'adjust':await adjustModal(id);break;
  case 'matching-plan':{S.data.plan=await api('/matching-plan');modalForm('调剂建议 · 需辅导员确认','matching-plan',`<div class="full">${table(['学生','专业','建议导师'],S.data.plan.map(p=>`<tr><td>${esc(p.student_name)}</td><td>${esc(p.major)}</td><td>${esc(p.advisor_name)}</td></tr>`),'暂无可用名额与同专业学生')}</div><label class="full">调剂备注<textarea name="reason" minlength="2" maxlength="1000" required>辅导员核对后确认同专业调剂建议</textarea></label>`,'确认执行本批调剂','规则：同专业优先、成绩降序；优先已有志愿，再按可用名额分配。不进行跨专业自动调剂。');break;}
  case 'import':importModal(id);break;
  case 'import-people':modal('选择导入类型',`<p class="subtitle">导师信息长期维护；学生信息归属当前学年。</p><div class="form-actions">${btn('导入导师','import','advisors','secondary','upload')}${btn('导入学生','import','students','','upload')}</div>`);break;
  case 'export':await download(id);break;
  case 'export-major':await download('results',document.getElementById('report-major').value);break;
  case 'review-profile':{const p=S.data.requests.find(x=>x.id===Number(id));modalForm('审核导师公示资料','review-profile',`${[['bio','个人简介'],['direction','研究方向'],['projects','科研项目'],['achievements','科研成果'],['notice','招生说明']].map(([k,t])=>`<section class="detail-section full"><h3>${t}</h3><p>${esc(p.content[k]||'未填写')}</p></section>`).join('')}${p.status==='pending'?`<label class="full">审核结果<select name="decision"><option value="accept">通过并发布</option><option value="reject">退回修改</option></select></label><label class="full">审核说明<textarea name="note" maxlength="1000"></textarea></label>`:'<input type="hidden" name="readonly" value="1">'}`,p.status==='pending'?'提交审核结果':'关闭',`${p.advisor_name} · ${date(p.created_at)}`,id);break;}
  case 'new-year':modalForm('创建新学年','new-year','<label class="full">学年名称<input name="name" placeholder="例如：2027级研究生" maxlength="50" required></label>','创建学年','当前学年需先归档。导师信息保留，新学年名额从零开始配置。');break;
  case 'activate-year':confirmation('切换学年','仅当当前学年处于准备或归档状态时可以切换。历史学年仍按其状态保持只读。','activate-year',id);break;
  case 'open-round1':confirmation('开启首轮双选','将按已保存的时间窗口开放填报与审核，并通知师生。','open-round1','','确认开启');break;
  case 'open-round2':{modalForm('手动开启二轮补选','open-round2',`<label>二轮开始时间<input type="datetime-local" name="start" value="${localInput(new Date(Math.ceil(Date.now()/60000)*60000))}" required></label><label>二轮截止时间<input type="datetime-local" name="end" value="${localInput(new Date(Date.now()+3*86400000))}" required></label>`,'确认开启二轮','请先完成名额微调。仅首轮未匹配学生可参与，时间为北京时间。默认从下一分钟开始。');break;}
  case 'close-round':confirmation('提前关闭本轮双选','关闭后所有待审核志愿失效，填报与导师审核停止，已配对结果保持锁定。','close-round',id,'确认关闭');break;
  case 'approve-results':confirmation('审核最终结果','请确认配对结果和异常调剂已核对完成。仅二轮关闭后可审核。','approve-results','','确认审核');break;
  case 'archive-results':confirmation('归档本学年','归档后本学年配对结果与招生名额不可更改。请先导出报表并完成审核。','archive-results','','确认归档');break;
  case 'reminder':modalForm('发送工作提醒','reminder','<label class="full">提醒对象<select name="audience"><option value="students">本届未匹配学生</option><option value="advisors">有待审核意向的导师</option></select></label><label class="full">提醒内容<textarea name="message" maxlength="1000" required placeholder="请及时完成本轮双选工作。"></textarea></label>','发送站内提醒');break;
  case 'read-notifications':await api('/notifications/read','POST');toast('消息已全部标为已读');await navigate();break;
  case 'verify-audit':{const r=await api('/audit/verify');toast(r.valid?`日志完整性验证通过，共 ${r.count} 条记录`:`日志异常：第 ${r.broken_at} 条`,!r.valid);break;}
}}catch(e){toast(e.message,true);}});

document.addEventListener('input',event=>{if(event.target.id!=='search')return;S.search=event.target.value;if(S.page==='directory')document.getElementById('directory-list').innerHTML=directoryCards();if(S.page==='people')document.getElementById('people-table').innerHTML=userRows();if(S.page==='quotas')document.getElementById('quota-table').innerHTML=quotaRows();});
document.addEventListener('change',async event=>{try{if(event.target.id==='major-filter'){S.major=event.target.value;document.getElementById('directory-list').innerHTML=directoryCards();}if(event.target.id==='intent-sort'){S.data.applications=await api('/applications?sort='+event.target.value);document.getElementById('intent-table').innerHTML=applicationTable(S.data.applications,true);}}catch(e){toast(e.message,true);}});

document.addEventListener('submit',async event=>{const f=event.target;if(!f.dataset.form)return;event.preventDefault();const type=f.dataset.form,id=f.dataset.id||'';const fd=new FormData(f),d=Object.fromEntries(fd.entries());const submit=f.querySelector('[type="submit"]')||f.querySelector('button:not([type="button"])');if(submit?.disabled)return;if(submit)submit.disabled=true;f.querySelector('.error-box').textContent='';let message='操作成功';try{switch(type){
  case 'login':{const r=await api('/login','POST',d);S.user=r.user;S.csrf=r.csrf;S.personRole='';shell();await navigate('overview');return;}
  case 'password':await api('/password','POST',d);dialog.close();S.user=null;S.csrf='';renderLogin();toast('密码已修改，请重新登录');return;
  case 'choice':await api('/applications','POST',{advisor_id:Number(d.advisor_id),rank:Number(d.rank)});message='志愿已提交';break;
  case 'edit-choice':await api('/applications/'+id,'PUT',{advisor_id:Number(d.advisor_id),rank:Number(d.rank)});message='志愿已更新';break;
  case 'cancel-choice':await api('/applications/'+id,'DELETE');message='志愿已撤回';break;
  case 'review-intent':await api(`/applications/${id}/review`,'POST',d);message=d.decision==='accept'?'配对已确认并锁定':'意向已拒绝，学生填报权限已释放';break;
  case 'user':await api('/users','POST',{...d,score:Number(d.score)});message='账号已新增';break;
  case 'edit-user':await api('/users/'+id,'PUT',{...d,score:Number(d.score),enabled:fd.has('enabled')});message='基础信息已保存';break;
  case 'grants':await api(`/users/${id}/grants`,'PUT',{grants:fd.getAll('grants')});message='岗位权限已更新';break;
  case 'reset-password':await api(`/users/${id}/reset-password`,'POST',d);message='密码已重置';break;
  case 'quota':await api('/quotas/'+id,'PUT',{total:Number(d.total)});message='招生名额已更新';break;
  case 'adjust':await api('/matches/adjust','POST',{student_id:Number(d.student_id),advisor_id:d.advisor_id?Number(d.advisor_id):null,reason:d.reason});message='配对已调整，相关师生已收到通知';break;
  case 'matching-plan':{if(!S.data.plan.length)throw Error('没有可执行的调剂建议');const r=await api('/matches/batch','POST',{assignments:S.data.plan.map(p=>({student_id:p.student_id,advisor_id:p.advisor_id})),reason:d.reason});message=`已确认 ${r.count} 组调剂配对`;break;}
  case 'import':{if(!d.file.size)throw Error('请选择 Excel 文件');const r=await api('/import/'+d.kind,'POST',d.file);message=`成功导入 ${r.count} 条数据`;break;}
  case 'profile':await api('/profile','POST',d);message='资料已提交审核';break;
  case 'review-profile':if(d.readonly){dialog.close();return;}await api(`/profile-requests/${id}/review`,'POST',d);message='资料审核已完成';break;
  case 'rules':{const caps={};for(const row of d.major_caps.split('\n').map(s=>s.trim()).filter(Boolean)){const parts=row.split('=');if(parts.length!==2||!parts[0].trim()||!/^\d+$/.test(parts[1].trim()))throw Error('专业上限请按“专业=非负整数”填写，每行一项');if(parts[0].trim() in caps)throw Error('专业名不能重复');caps[parts[0].trim()]=Number(parts[1]);}await api('/rules','PUT',{wish_limit:Number(d.wish_limit),start:fromInput(d.start),end:fromInput(d.end),major_caps:caps});message='首轮规则已保存';break;}
  case 'new-year':await api('/years','POST',d);message='新学年已创建';break;
  case 'activate-year':await api(`/years/${id}/activate`,'POST');message='已切换学年';break;
  case 'open-round1':await api('/rounds/1/open','POST');message='首轮已开启';break;
  case 'open-round2':await api('/rounds/2/open','POST',{start:fromInput(d.start),end:fromInput(d.end)});message='二轮补选已开启';break;
  case 'close-round':await api(`/rounds/${id}/close`,'POST');message='本轮已关闭';break;
  case 'approve-results':await api('/results/approve','POST');message='最终结果已审核';break;
  case 'archive-results':await api('/results/archive','POST');message='本学年已归档';break;
  case 'reminder':{const r=await api('/reminders','POST',d);message=`已向 ${r.count} 人发送提醒`;break;}
}dialog.close();toast(message);await navigate();}catch(e){f.querySelector('.error-box').textContent=e.message;}finally{if(submit)submit.disabled=false;}});

async function boot(){try{const data=await api('/me');S.user=data.user;S.csrf=data.csrf;shell();await navigate();}catch{renderLogin();}}
setInterval(async()=>{if(!S.user)return;try{S.notifications=await api('/notifications');updateUnread();}catch{}},30000);
boot();
